{
  "avaliacoes": [
    {
      "id": "E0d958719befe3022",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O documento apresenta como problema recorrente a ausência de um sistema de gestão de integridade apto a identificar e mitigar questões de envelhecimento e fim de vida em FPSOs/FSUs.",
          "trechos": [
            "E0d958719befe3022:1386:2085"
          ],
          "condicoes": [
            "Contexto de FPSOs/FSUs no UKCS",
            "Baseado em lições de intervenções de HSE e OPRED"
          ],
          "limites": [
            "É orientação regulatória estrangeira, não requisito brasileiro",
            "O trecho descreve achados de fiscalização e atenção necessária, sem classificar formalmente tipos de anomalia"
          ]
        },
        {
          "proposicao": "Falhas de aderência ao programa definido de integridade, incluindo casco, estruturas de topside e equipamentos críticos de segurança e meio ambiente, aparecem como fatores relevantes para gestão de anomalias e barreiras.",
          "trechos": [
            "E0d958719befe3022:1386:2085"
          ],
          "condicoes": [
            "Aplicável ao regime de integridade adotado pela instalação",
            "Relaciona-se à execução do programa já definido"
          ],
          "limites": [
            "O trecho não fornece critérios de priorização, aceitação ou prazos",
            "Não detalha medidas compensatórias específicas"
          ]
        },
        {
          "proposicao": "Corrosão estrutural excessiva e baixa visibilidade de backlog de inspeção e manutenção diferida são apontadas como sinais operacionais relevantes para envelhecimento, rastreabilidade e controle de barreiras.",
          "trechos": [
            "E0d958719befe3022:2085:2377"
          ],
          "condicoes": [
            "Inclui backlog de casco submerso, tanques de carga/lastro e amarração",
            "Relaciona-se ao acompanhamento global do backlog de SECE"
          ],
          "limites": [
            "O trecho não define limiares quantitativos de corrosão ou backlog",
            "Não apresenta método de classificação de criticidade"
          ]
        }
      ]
    },
    {
      "id": "E2c3171af3c46e4ec",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O sistema de gestão de integridade deve prever arranjos para registrar, inspecionar, revisar e substituir reparos de vida definida, o que reforça a rastreabilidade de anomalias e reparos temporários.",
          "trechos": [
            "E2c3171af3c46e4ec:0:695"
          ],
          "condicoes": [
            "Aplicável ao gerenciamento de integridade da instalação",
            "Focado em reparos com vida definida"
          ],
          "limites": [
            "O trecho não informa critérios para definir vida do reparo",
            "Não diferencia, por si só, reparo temporário de permanente"
          ]
        },
        {
          "proposicao": "É indicada como boa prática a elaboração anual de um resumo de integridade por instalação, consolidando histórico de inspeções, reparos, anomalias pendentes, backlog, modificações, análises e incidentes, além das principais ameaças e atividades planejadas.",
          "trechos": [
            "E2c3171af3c46e4ec:0:695"
          ],
          "condicoes": [
            "Periodicidade anual",
            "Por instalação"
          ],
          "limites": [
            "Expressamente apresentado como boa prática, não como exigência universal",
            "O trecho não define formato padronizado nem conteúdo mínimo obrigatório fora desse contexto"
          ]
        },
        {
          "proposicao": "Na integridade estrutural de FPSOs/FSUs, o escopo, a metodologia e a frequência de inspeção devem ser adequados à idade e à condição da embarcação, e o sistema deve contemplar ameaças de envelhecimento, fim de vida e dano por fadiga estrutural.",
          "trechos": [
            "E2c3171af3c46e4ec:1393:2091",
            "E2c3171af3c46e4ec:2091:2397"
          ],
          "condicoes": [
            "Aplicável a FPSOs/FSUs",
            "No contexto do sistema de gestão de integridade"
          ],
          "limites": [
            "Não fornece frequência numérica nem técnica específica de inspeção",
            "A necessidade de recursos adicionais em fim de vida é exemplificativa, não exaustiva"
          ]
        }
      ]
    },
    {
      "id": "Ef3c7cfa7f3c06b00",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A revisão holística de anomalias em aberto, em intervalos adequados, é apresentada como meio para identificar causas subjacentes, ameaças globais de integridade e potencial de colapso progressivo.",
          "trechos": [
            "Ef3c7cfa7f3c06b00:0:695",
            "Ef3c7cfa7f3c06b00:695:1346"
          ],
          "condicoes": [
            "Aplicável a FPSOs/FSUs",
            "Pressupõe existência de anomalias registradas e acompanhamento periódico"
          ],
          "limites": [
            "O trecho não oferece taxonomia formal de anomalias",
            "Não define método analítico para detectar colapso progressivo"
          ]
        },
        {
          "proposicao": "Os limites permissíveis de carregamento do casco devem permanecer válidos à luz da configuração atual, idade e deteriorações ou defeitos observados, conectando avaliação de anomalias estruturais à manutenção de barreiras estruturais.",
          "trechos": [
            "Ef3c7cfa7f3c06b00:695:1346"
          ],
          "condicoes": [
            "Considera força cortante, momento fletor e deflexão",
            "Depende da configuração, idade e estado observado da estrutura"
          ],
          "limites": [
            "O trecho não apresenta valores-limite",
            "Não descreve procedimento de recálculo ou validação"
          ]
        },
        {
          "proposicao": "Na avaliação de risco de anomalias estruturais, deve-se considerar a possibilidade de perda de contenção, incluindo ingresso de oxigênio e liberação de hidrocarbonetos ou gás tóxico; além disso, reparos precisam atender aos critérios do padrão de desempenho correspondente.",
          "trechos": [
            "Ef3c7cfa7f3c06b00:695:1346",
            "Ef3c7cfa7f3c06b00:1346:2040"
          ],
          "condicoes": [
            "Aplicável ao tratamento de anomalias estruturais e reparos",
            "Exemplos de consequências incluem liberação de gás tóxico e hidrocarbonetos"
          ],
          "limites": [
            "Os exemplos de consequências não esgotam os cenários possíveis",
            "O trecho não especifica critérios de aceitação do reparo além do atendimento ao padrão de desempenho"
          ]
        }
      ]
    },
    {
      "id": "E8112ae5b2cabd595",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A revisão completa deve considerar mudanças em parâmetros de projeto, envelhecimento da instalação e alterações nas condições operacionais que possam influenciar a operação segura, de modo a confirmar se o safety case permanece adequado até a próxima revisão.",
          "trechos": [
            "E8112ae5b2cabd595:0:695"
          ],
          "condicoes": [
            "No âmbito do processo de thorough review",
            "Ligado à adequação contínua do safety case"
          ],
          "limites": [
            "Refere-se ao regime regulatório do Reino Unido",
            "Não detalha critérios de aceitação para cada tipo de mudança"
          ]
        },
        {
          "proposicao": "Ao atingir o fim da vida de projeto original, a instalação deve passar por avaliação formal de extensão de vida para verificar a adequação à continuidade segura da operação.",
          "trechos": [
            "E8112ae5b2cabd595:695:1392"
          ],
          "condicoes": [
            "Para instalações próximas ou no fim da vida de projeto original"
          ],
          "limites": [
            "O trecho não fornece metodologia detalhada da avaliação",
            "Não implica que toda instalação será automaticamente aprovada para continuar operando"
          ]
        },
        {
          "proposicao": "A avaliação formal de extensão de vida deve demonstrar a reavaliação dos riscos de acidentes maiores e a manutenção da integridade em nível tão alto quanto razoavelmente praticável; conforme o resultado, pode ser necessária submissão de mudança material no safety case.",
          "trechos": [
            "E8112ae5b2cabd595:695:1392"
          ],
          "condicoes": [
            "Dependente do resultado das avaliações conduzidas",
            "Focada em riscos a pessoas decorrentes de questões de integridade"
          ],
          "limites": [
            "Critério ALARP/LARP pertence ao contexto regulatório citado",
            "A necessidade de mudança material é condicional, não automática"
          ]
        }
      ]
    },
    {
      "id": "E2964a7c1d422d6c4",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A viabilidade e a extensão da continuação de serviço além da vida de projeto são influenciadas por desafios operacionais e ambientais, como exposição mais severa que a prevista, atualização de dados meteoceanográficos e mudanças em química da água e biologia marinha com corrosão química e biológica excessiva.",
          "trechos": [
            "E2964a7c1d422d6c4:698:1396"
          ],
          "condicoes": [
            "Contexto de unidades flutuantes de produção envelhecidas",
            "Comparação com a base original de projeto"
          ],
          "limites": [
            "Trecho explicativo, sem hierarquizar riscos nem definir critérios de aceitação",
            "Documento com fronteiras documentais incertas no corpus concatenado"
          ]
        },
        {
          "proposicao": "Processos eficazes de manutenção e regimes de inspeção são apresentados como elementos capazes de contrabalançar, ao menos em parte, os efeitos dos desafios que afetam a vida útil.",
          "trechos": [
            "E2964a7c1d422d6c4:698:1396"
          ],
          "condicoes": [
            "No contexto de princípios de gestão de integridade de ativos"
          ],
          "limites": [
            "O texto não demonstra quantitativamente o efeito compensatório",
            "Não especifica técnicas, frequências ou limites operacionais"
          ]
        },
        {
          "proposicao": "Uma metodologia de extensão de vida é descrita como devendo ser robusta e flexível, incluindo avaliação abrangente da unidade para determinar se a integridade estrutural e mecânica permite operar além da vida de projeto com segurança.",
          "trechos": [
            "E2964a7c1d422d6c4:1396:2092"
          ],
          "condicoes": [
            "Objetivo de continuidade operacional segura além da vida de projeto",
            "Com mitigação de riscos e minimização de perdas de produtividade"
          ],
          "limites": [
            "Formulação descritiva de alto nível, sem procedimento detalhado",
            "Não constitui norma ou requisito brasileiro"
          ]
        }
      ]
    },
    {
      "id": "E58a4b81ed1383d81",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Regime de inspeção reforçado, com aumento de frequência e/ou uso de técnicas diferentes, inclusive ensaios não destrutivos em lugar de mera inspeção visual, é apresentado como medida possível dentro do processo de extensão de vida.",
          "trechos": [
            "E58a4b81ed1383d81:0:698"
          ],
          "condicoes": [
            "No contexto de medidas implementadas para viabilizar operação segura",
            "Pode envolver mudança de técnica de inspeção"
          ],
          "limites": [
            "O trecho não define quando essa intensificação é necessária",
            "Não traz critérios comparativos entre técnicas"
          ]
        },
        {
          "proposicao": "A disponibilidade de documentos de projeto original, análises, relatórios de inspeção e reparo, além de registros de modificações, é apontada como aspecto relevante para o sucesso da extensão de vida, reforçando a rastreabilidade documental.",
          "trechos": [
            "E58a4b81ed1383d81:698:1391"
          ],
          "condicoes": [
            "Dependente da manutenção de registros pelo proprietário/operador"
          ],
          "limites": [
            "O trecho não define padrão mínimo de controle documental",
            "Não assegura, por si só, adequação estrutural ou mecânica"
          ]
        },
        {
          "proposicao": "Um programa robusto de gestão de integridade e os registros da sociedade classificadora são tratados como bases de referência para condição estrutural, mecânica e de sistemas de segurança, com papel de interface junto a autoridades estatutárias e regulatórias.",
          "trechos": [
            "E58a4b81ed1383d81:698:1391",
            "E58a4b81ed1383d81:1391:2091"
          ],
          "condicoes": [
            "No processo de extensão de vida de unidades flutuantes",
            "Com participação da sociedade classificadora"
          ],
          "limites": [
            "O texto não substitui exigências regulatórias específicas aplicáveis",
            "O papel da classificadora é descrito de forma geral"
          ]
        }
      ]
    }
